package com.portfolio.controller;
import com.portfolio.model.Testimonial; import com.portfolio.repository.TestimonialRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/testimonials") public class TestimonialController { private final TestimonialRepository repo; public TestimonialController(TestimonialRepository r){repo=r;} @GetMapping public List<Testimonial> all(){return repo.findAllByOrderByDisplayOrderAsc();} @GetMapping("/{id}") public ResponseEntity<Testimonial> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public Testimonial create(@RequestBody Testimonial x){return repo.save(x);} @PutMapping("/{id}") public ResponseEntity<Testimonial> update(@PathVariable Long id,@RequestBody Testimonial p){return repo.findById(id).map(x->{
x.setName(p.getName());x.setRole(p.getRole());x.setCompany(p.getCompany());x.setQuote(p.getQuote());x.setImage(p.getImage());x.setDisplayOrder(p.getDisplayOrder());return ResponseEntity.ok(repo.save(x));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }